css:
.fx-plx{background:var(--surface)}
.fx-plx .stage{position:relative;height:min(92vh,760px);overflow:hidden;background:linear-gradient(180deg,color-mix(in srgb,var(--accent) 55%,#fff),color-mix(in srgb,var(--primary) 18%,var(--surface)))}
.fx-plx .ly{position:absolute;left:0;right:0;bottom:-12%;height:70%;will-change:transform;transform:translate3d(0,calc(var(--y,0)*var(--k,0)*1px),0)}
.fx-plx .ly svg{display:block;width:100%;height:100%}
.fx-plx .sun{position:absolute;right:16%;top:16%;width:clamp(70px,12vw,150px);aspect-ratio:1;border-radius:50%;background:color-mix(in srgb,var(--accent) 35%,#fff);will-change:transform;transform:translate3d(0,calc(var(--y,0)*.12px),0)}
.fx-plx .ttl{position:absolute;left:0;right:0;top:22%;width:min(1000px,90%);margin:0 auto;will-change:transform,opacity;transform:translate3d(0,calc(var(--y,0)*.5px),0);opacity:calc(1 - var(--y,0)/520)}
.fx-plx .ttl .k{font-size:.78em;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--primary)}
.fx-plx .ttl h2{font-size:clamp(2.2em,6.5vw,4.6em);margin:.25em 0 .2em;max-width:12ch;color:var(--primary)}
.fx-plx .ttl p{opacity:.8;max-width:34ch;color:var(--primary)}
.fx-plx .l1 svg{fill:color-mix(in srgb,var(--primary) 30%,var(--surface))}
.fx-plx .l2 svg{fill:color-mix(in srgb,var(--primary) 58%,var(--surface))}
.fx-plx .l3 svg{fill:var(--primary)}
.fx-plx .after{width:min(680px,90%);margin:0 auto;padding:4em 0 6em}
.fx-plx .after h3{font-size:1.8em;margin-bottom:.5em}.fx-plx .after p{opacity:.8;line-height:1.7}
@media(prefers-reduced-motion:reduce){.fx-plx .ly,.fx-plx .sun,.fx-plx .ttl{transform:none!important;opacity:1!important}}
